def comb_gray(n,k):
 if k==0:return [set()]
 if k==n:return [set(range(n))]
 a=comb_gray(n-1,k)
 b=comb_gray(n-1,k-1)
 return a+[s|{n-1} for s in reversed(b)]
cs3=comb_gray(8,3)
print(len(cs3),all(len(cs3[i]^cs3[i-1])==2 for i in range(1,len(cs3))))
